'use strict';
function moreActions(body,label='Plus d’options'){return `<details class="more-actions"><summary>${label}</summary><div>${body}</div></details>`;}
function intent(t,s,a,o,i){return A(`<span class="intent-icon">${icon(i)}</span><span><strong>${t}</strong><small>${s}</small></span>${icon('chev')}`,a,o,'glass intent-row');}
function recommendations(domain){const counts={};return CATALOG.filter(x=>x.type==='Look'&&(!domain||x.domain===domain)&&M.contentFeedback?.[x.id]!=='less'&&!x.referenceOnly).sort((a,b)=>lookRank(b)-lookRank(a)).filter(x=>{counts[x.domain]=(counts[x.domain]||0)+1;return !!domain||counts[x.domain]<=2;}).slice(0,4);}
Object.assign(V,{
 'ENT-01':()=>head('On reprend ?',M.profile.name?'Heureuse de vous retrouver, '+esc(M.profile.name)+'.':'Votre espace vous attend.')+(M.draft.status!=='complete'&&(M.draft.photo||Object.keys(M.draft.answers).length)?panel(tag('En cours')+P('Votre analyse '+esc(M.draft.domain.toLowerCase()))+B('Reprendre mon analyse',M.draft.phase)): '')+B('Voir ma journée','ACC-01')+B('Trouver une inspiration','DEC-01','secondary mt')+note('Vos essais sont conservés dans cet onglet.'),
 'ENT-02':()=>`<div class="welcome-brand">${logo(true)}</div><div class="welcome-editorial">${imageFor('boucles-libres','','Portrait éditorial, boucles naturelles')}<span class="editorial-caption">Beauté. Style. Vous.</span></div><div class="welcome-copy"><h1 tabindex="-1">Vos envies,<br><span class="accent">votre rythme.</span></h1>${P('Un look à essayer. Une occasion à préparer. Un rituel à vous.')}${B('Trouver mon inspiration','ENT-03')}${B('Explorer librement','DEC-01','secondary mt')}${B('J’ai déjà un compte','ENT-06','text-button mt')}</div>`,
 'ENT-03':()=>head('Une envie pour commencer ?','Votre premier raccourci, vous pourrez explorer le reste ensuite.')+intent('Trouver un look rapide','Des idées faciles, selon mon temps','start-intent',{intent:'look'},'sparkles')+intent('Préparer une occasion','Réunir coiffure, maquillage et tenue','start-intent',{intent:'event'},'calendar')+intent('Créer un rituel à moi','Quelques gestes que j’ai envie de garder','start-intent',{intent:'routine'},'sun')+B('Je préfère explorer librement','DEC-01','text-button mt'),
 'ENT-04':()=>head('Une inspiration à ma mesure','Un premier repère suffit. Vous pourrez affiner ensuite.')+form('onboarding',select('time','Combien de temps aujourd’hui ?',['Moins de 5 min','10–15 min','20–30 min','Sans préférence'],M.prefs.time)+moreActions(chips(DOMAINS.map(d=>d[0]),'interests',M.prefs.interests)+select('makeup','Mon envie de maquillage',['Discret','Défini','Intense','Sans maquillage','Sans préférence'],M.prefs.makeup),'Mes univers et mes envies'),'Trouver mes premières idées'),
 'ACC-01':()=>{const actions=dailyActions(),next=M.events.filter(e=>e.date>=DATE()&&e.status!=='done').sort((a,b)=>a.date.localeCompare(b.date))[0],again=M.sessions.filter(s=>s.kind==='tutorial').at(-1);return head(M.profile.name?'Bonjour '+esc(M.profile.name):'Un moment pour vous',dateText(DATE()))+sec('Pour aujourd’hui','ACC-03','Ma journée')+(actions.length?actions.slice(0,2).map(taskRow).join(''):intent('Un look en quelques minutes','Une idée facile à essayer aujourd’hui','catalog',{time:'5 minutes',type:'Look'},'sparkles'))+`<div class="quick-links">${B(icon('calendar')+' Ma semaine','ACC-02','secondary')}${B(icon('sun')+' Mes routines','ROU-01','secondary')}</div>`+(next?sec('Mon occasion à préparer','EVE-01')+eventCard(next):intent('Préparer une occasion','Rassembler mon look et mes essentiels','new-event',{},'calendar'))+sec('Une inspiration pour moi','DEC-01')+grid(recommendations().slice(0,2))+(again&&item(again.ref)?row('Retrouver mon dernier look',esc(item(again.ref).name),'DEC-03','heart',{key:'look',value:again.ref}):'')+moreActions(B('Mon journal et mes habitudes','PRO-01','secondary')+B('Toutes mes occasions','EVE-01','secondary mt')+B('Mes messages','ACC-04','secondary mt'),'Retrouver mon espace')},
 'ACC-02':()=>{const start=weekStart(M.weekDate||DATE());return head('Ma semaine','Quelques idées prêtes, de la place pour vos envies.')+`<div class="week-heading">${A(icon('back'),'week-move',{delta:-7,label:'Semaine précédente'},'icon-button')}<span>${shortDate(start)} – ${shortDate(addDays(start,6))}</span>${A(icon('arrow'),'week-move',{delta:7,label:'Semaine suivante'},'icon-button')}</div>`+Array.from({length:7},(_,i)=>{const date=addDays(start,i),actions=dailyActions(date),names=actions.map(a=>a.name);return A(`<span class="week-date"><strong>${new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'})}</strong><small>${date.slice(-2)}</small></span><span><strong>${names.length?esc(names[0]):'À votre rythme'}</strong><small>${names.length>1?'+'+(names.length-1)+' autre'+(names.length>2?'s':'')+' moment'+(names.length>2?'s':''):date===DATE()?'Aujourd’hui':names.length?'Prêt à retrouver':'Une journée libre'}</small></span>${icon('chev')}`,'open-day',{date},'glass week-row '+(date===DATE()?'today':''));}).join('')+A('Me proposer 3 idées','suggest-week')+note('Vous choisissez les jours et pouvez remplacer chaque idée avant de la garder.')+moreActions(B('Mes routines et leurs rythmes','ROU-01','secondary')+A('Ajouter une action personnelle','add-action',{},'secondary mt'))},
 'ACC-03':()=>{const date=M.day||DATE(),list=dailyActions(date);return head('Ma journée',dateText(date))+(M.feedbackLook?lookFeedbackPanel(M.feedbackLook):'')+form('day',field('date','Choisir un autre jour',date,'date'),'Afficher')+(list.length?list.map(taskRow).join(''):empty('Une journée libre','Vous pouvez choisir une inspiration ou garder ce temps pour vous.','DEC-01','Une idée pour moi'))+A('Ajouter une action','add-action',{},'text-button mt')+moreActions(form('day-note',area('note','Ce que je retiens de cette journée',M.dayNotes[date]||''),'Garder ma note')+B('Ouvrir tout mon journal','PRO-01','text-button mt'),'Une note pour moi')},
 'ACC-04':()=>{const messages=M.messages.filter(m=>!isRetiredRoute(m.route)&&m.objectKey!=='event');return head('Messages','Les nouvelles de votre espace.')+(messages.length?messages.slice().reverse().map(m=>panel(`${tag(m.read?'Lu':'Nouveau')}${P(esc(m.text))}${A('Ouvrir','message',{id:m.id},'secondary')}`)).join(''):empty('Vous êtes à jour','Vos comptes rendus et rappels apparaîtront ici.','PRF-05','Mes rappels'));},
 'DEC-01':()=>head('Une envie à explorer','Trouvez ce qui vous parle aujourd’hui.')+A(icon('search')+' Rechercher un look, un produit…','catalog',{},'search-entry')+`<div class="universe-list">${DOMAINS.map(([t,i,p])=>B(icon(i)+`<span>${({Colorimétrie:'Couleurs','Garde-robe':'Tenues'})[t]||t}</span>`,p,'universe')).join('')}</div>`+sec('Selon vos envies','PRF-03','Affiner')+grid(recommendations())+sec('Pour votre quotidien')+row('Mes pièces, mes tenues','Composer avec ce que j’ai','GAR-02','hanger')+A('Tutoriels '+icon('arrow'),'catalog',{type:'Tutoriel'},'secondary mt')+A('Explorer les produits '+icon('arrow'),'catalog',{type:'Produit'},'secondary mt')+note('Sélection éditoriale selon vos préférences déclarées.'),
 'DEC-02':()=>head(M.context.selection?'Choisir une inspiration':'Trouver une inspiration')+selectedBanner()+(M.context.selection?chips(['Inspirations','Mes enregistrés'],'selectionSource',M.selectionSource||'Inspirations'):'')+`<div class="search-toolbar"><label class="sr-only" for="catalog-search">Rechercher dans les inspirations</label><input class="search-input" id="catalog-search" type="search" value="${esc(M.filters.q)}" placeholder="Un look, une couleur, une envie…">${!M.context.selection?A(icon('settings'),'catalog-filters',{label:'Ouvrir les filtres'},'icon-button'):''}</div>`+(!M.context.selection&&activeFilters()?`<div class="active-filters">${tag(filterDescription())}${A('Effacer','reset-filters',{},'text-button')}</div>`:'')+`<div id="catalog-results">${catalogResults()}</div>`,
 'DEC-03':()=>{const x=currentLook();if(!x||x.type!=='Look')return empty('Cette inspiration n’est plus disponible','Retrouvez vos autres idées.','DEC-01','Découvrir');return `<div class="look-cover">${imageFor(x.image,'detail-photo',x.name)}${A(icon(M.saved.includes(x.id)?'check':'bookmark'),'save',{id:x.id,label:'Enregistrer '+x.name,pressed:M.saved.includes(x.id)},'heart-save')}</div>`+head(esc(x.name),`${x.minutes?x.minutes+' min, ':''}${esc(x.domain==='Personnel'?'Ma création':x.domain)}`)+P(esc(x.desc||'Une composition à votre rythme.'))+(M.context.selection?'':A(tutorialLabel(x),'tutorial',{id:x.id}))+lookContents(x)+moreActions(A('Prévoir pour un autre jour','plan-look',{id:x.id},'secondary')+A('Classer dans mes enregistrés','classify',{id:x.id},'secondary mt')+(!x.pieces&&!x.components&&!x.referenceOnly?B('Voir un rendu illustratif','ESS-01','secondary mt'):'')+(x.pieces?A('Modifier cette tenue','edit-outfit',{id:x.id},'secondary mt'):''))+sec('Avant de me lancer')+lookPractical(x)+moreActions(P(esc(x.why||'Cette création rassemble mes propres choix.'))+A('Voir moins d’idées comme celle-ci','look-less',{id:x.id},'text-button'),'Pourquoi cette idée ?')+(x.products?.length?sec('Les produits du look')+grid(x.products.map(item)): '');},
 'DEC-04':()=>{const x=currentLook();if(!x)return empty('Ce look n’est plus disponible','Choisissez une autre idée.','DEC-01');const steps=x.steps||['Préparer les pièces choisies.','Composer le look.','Ajuster selon vos envies.'],i=Math.min(M.tutorialStep,steps.length-1);return head(esc(x.name),'Le pas à pas')+progress(i+1,steps.length)+imageFor(x.image,'tutorial-photo',x.name)+panel(`<span class="eyebrow">Étape ${i+1}</span><h2>${esc(steps[i])}</h2>`)+(i<steps.length-1?A('Étape suivante','tutorial-step',{delta:1,total:steps.length}):A(x.referenceOnly?'Ma référence est prête':'J’ai réalisé ce look',x.referenceOnly?'salon-ready':'tutorial-complete'))+(i>0?A('Étape précédente','tutorial-step',{delta:-1},'secondary mt'):'')+moreActions(`<ol class="all-steps">${steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>${A('J’ai seulement consulté le tutoriel','tutorial-read',{},'text-button')}`,'Voir toutes les étapes');},
 'DEC-05':()=>head('Associer les couleurs simplement')+imageFor('portrait','article-photo','Inspiration de couleurs chaudes')+`<article class="article-copy"><h2>Une couleur que vous aimez</h2><p>Choisissez une pièce ou une teinte que vous avez envie de porter. Elle devient le point de départ de votre association.</p><h2>Une base neutre</h2><p>Un crème, un brun ou un gris peut laisser de la place à votre couleur principale. Regardez les nuances ensemble, dans la lumière où vous porterez votre look.</p><h2>Une matière qui vous plaît</h2><p>Une teinte change d’allure sur une matière mate, satinée ou texturée. Gardez l’association dans laquelle vous vous sentez à l’aise.</p></article>`+B('Explorer les nuances','COL-01')+A('Enregistrer ce conseil','save',{id:'article-colors'},'secondary mt'),
 'DEC-06':()=>{const x=item(M.context.product);if(!x||x.type!=='Produit')return empty('Produit indisponible','Retrouvez les autres références.','DEC-01');const meta=PRODUCT_DETAILS[x.id];return head(esc(x.name))+imageFor(x.image,'product-photo',x.name)+P(esc(meta.summary))+`<div class="product-price">${money(x.price)} <small>Produit et prix fictifs</small></div>`+form('product',`<fieldset class="shade-field"><legend>Choisir ma nuance</legend>${x.variants.map((v,i)=>{const shade=meta.shades[i];return `<label class="shade-choice"><input type="radio" name="variant" value="${esc(v)}" ${i===0?'checked':''}><i style="--shade:${shade[0]}"></i><span><strong>${esc(v)}</strong><small>${esc(shade[1])}</small></span></label>`;}).join('')}</fieldset>`+field('qty','Quantité',1,'number',true),'Ajouter au panier — démo')+note('Les pastilles sont illustratives. Elles ne prédisent pas le rendu sur votre peau.')+moreActions(P(esc(meta.details))+A('Garder ce produit','save',{id:x.id},'secondary')+A('L’associer à ma routine','product-routine',{id:x.id},'secondary mt')+B('Où le trouver ?','ACH-01','text-button mt'),'Détails et autres options')},
});
function preferencesForm(id){const p=id==='preferences'?(M.preferenceEdit||M.prefs):M.prefs;return form(id,select('hair','Texture de cheveux',['Raides','Ondulés','Bouclés','Crépus','Je ne sais pas'],p.hair)+select('time','Temps disponible',['Moins de 5 min','10–15 min','20–30 min','Sans préférence'],p.time)+select('makeup','Envie de maquillage',['Discret','Défini','Intense','Sans maquillage','Sans préférence'],p.makeup)+select('style','Style apprécié',['Sans préférence','Naturel','Minimaliste','Élégant','Créatif'],p.style)+field('budget','Budget indicatif — facultatif',p.budget)+area('avoid','Ce que je préfère éviter — facultatif',p.avoid),'Garder mes préférences');}
function taskRow(a){const archived=a.kind==='routine'&&!M.routines.some(r=>r.id===a.ref);return `<div class="glass check-task ${a.done?'done':''}">${archived?`<span class="icon-button" aria-hidden="true">${icon(a.done?'check':'sun')}</span>`:A(`<span class="check-circle">${a.done?icon('check'):''}</span>`,'task',{id:a.id,pressed:a.done,label:(a.done?'Marquer à faire : ':'Marquer faite : ')+a.name},'icon-button')}<span class="label"><strong>${esc(a.name)}</strong><small>${dateText(a.date)}, ${a.done?'Faite':archived?'Séance conservée':'À faire'}</small></span>${A(icon('chev'),'task-open',{id:a.id,label:(archived?'Revoir ':'Commencer ')+a.name},'icon-button')}${!archived?A(icon('more'),'task-options',{id:a.id,label:'Options pour '+a.name},'icon-button'):''}</div>`;}
function activeFilters(){const f=M.filters;return f.domain!=='Tous'||f.type!=='Tous'||f.occasion!=='Toutes'||f.time!=='Tous'||f.budget!=='Tous';}
function filterDescription(){return [M.filters.domain,M.filters.type,M.filters.occasion,M.filters.time,M.filters.budget].filter(v=>!['Tous','Toutes'].includes(v)).map(esc).join(', ');}
function catalogResults(){const f=M.filters,s=M.context.selection;let source=s&&M.selectionSource==='Mes enregistrés'?M.saved.map(item).filter(Boolean):[...CATALOG.filter(x=>x.type!=='Routine'),...M.routines];if(s?.kind==='event')source=[...source,...(M.selectionSource==='Mes enregistrés'?[]:M.outfits.filter(x=>x.pieces))];let xs=source.filter(x=>(!s||canSelect(x,s))&&(!s?(f.domain==='Tous'||x.domain===f.domain)&&(f.type==='Tous'||x.type===f.type)&&(f.occasion==='Toutes'||x.occasion===f.occasion||x.occasion==='Toutes'):true)&&(!f.q||fold(x.name+' '+(x.desc||'')+' '+x.domain).includes(fold(f.q)))&&(!s?(f.time==='Tous'||x.minutes<=(f.time==='5 minutes'?5:15))&&(f.budget==='Tous'||(f.budget==='Sans achat'?x.budget==='Sans achat':x.type==='Produit'&&x.price<30)):true));if(M.scenario==='empty')xs=[];if(s?.kind==='event')xs.sort((a,b)=>(b.occasion===M.events.find(e=>e.id===s.eventId)?.occasion?1:0)-(a.occasion===M.events.find(e=>e.id===s.eventId)?.occasion?1:0));return sec(`${xs.length} idée${xs.length>1?'s':''}`)+(s?.kind==='event'?note('Les idées de votre occasion apparaissent d’abord. Vous pouvez aussi choisir une autre inspiration.'): '')+(xs.length?grid(xs):empty('Aucune correspondance','Essayez un autre mot ou élargissez vos choix.')+A(s?'Voir toutes les inspirations':'Effacer les filtres','reset-filters',{},'secondary'));}
Object.assign(F,{
 'onboarding':d=>{Object.assign(M.prefs,{time:d.time,makeup:d.makeup||M.prefs.makeup});M.started=true;go('DEC-01',{root:true});},
 preferences:d=>{Object.assign(M.prefs,M.preferenceEdit||{},d);M.preferenceEdit=null;go('PRF-01');toast('Préférences mises à jour.');},
 day:d=>{M.day=d.date;render({scroll:0});},
 'day-note':d=>{M.dayNotes[M.day||DATE()]=d.note;toast('Note gardée pour cette journée.');},
 product:d=>{const id=M.context.product,x=item(id);if(!x||!x.variants.includes(d.variant))return formError('Choisissez une nuance disponible.');const qty=Math.min(99,Math.max(1,Number(d.qty)||1)),line=M.cart.find(c=>c.id===id&&c.variant===d.variant);if(line)line.qty=Math.min(99,line.qty+qty);else M.cart.push({id,variant:d.variant,qty});go('ACH-02');},
 action:d=>{M.actions.push({id:uid('action'),name:d.name,date:d.date,done:false,kind:'custom'});closeModal();render();},
 reschedule:d=>{const a=findAction(M.context.action);if(a){if(a.id.startsWith('due:')){M.skippedOccurrences.push(a.ref+':'+a.date);addPlan(item(a.ref),d.date);}else{const original=M.actions.find(x=>x.id===a.id);original.date=d.date;original.done=false;}}closeModal();render();},
 'plan-look':d=>{addPlan(item(M.context.planLook),d.date);closeModal();toast('Prévu pour le '+dateText(d.date)+'.');},
 'product-routine':d=>{const r=M.routines.find(r=>r.id===d.routine),x=item(M.context.product);if(!r||!x)return formError('Choisissez une routine.');r.products||=[];if(!r.products.includes(x.id))r.products.push(x.id);closeModal();toast('Produit ajouté à '+r.name+'.');}
});
Object.assign(ACTIONS,{
 'interests-next':()=>go('ENT-04'),
 'reset-filters':()=>{M.filters=defaultFilters();M.selectionSource='Inspirations';render();},
 'tutorial':d=>{M.tutorialStep=0;go('DEC-04',{context:{look:d.id,eventTutorial:null,eventTutorialDate:null,eventTutorialDomain:null}});},
 'tutorial-step':d=>{M.tutorialStep=Math.max(0,M.tutorialStep+Number(d.delta));render({scroll:0,focus:true});},
 'tutorial-complete':()=>{const x=currentLook();if(!x)return;const date=M.context.eventTutorialDate||DATE(),key='tutorial-'+x.id+'-'+date;if(!M.sessions.some(s=>s.id===key))M.sessions.push({id:key,date,kind:'tutorial',ref:x.id,name:x.name,confirmed:true});M.actions.filter(a=>a.ref===x.id&&a.date===date).forEach(a=>a.done=true);M.feedbackLook=x.id;M.day=date;if(M.context.eventTutorial){const e=M.events.find(e=>e.id===M.context.eventTutorial);if(e){e.tasks[M.context.eventTutorialDomain]=true;go('EVE-05',{context:{event:e.id,eventTutorial:null,eventTutorialDate:null,eventTutorialDomain:null}});return;}}go('ACC-03',{context:{eventTutorialDate:null}});toast('Ce moment est gardé dans votre suivi.');},
 'tutorial-read':()=>{go('DEC-03');toast('Tutoriel consulté. Aucune réalisation ajoutée au suivi.');},
 'plan-look':d=>{M.context.planLook=d.id;modal('Prévoir ce look',form('plan-look',field('date','Pour quel jour ?',DATE(),'date',true),'Planifier'));},
 'add-action':()=>modal('Une action pour vous',form('action',field('name','Que souhaitez-vous faire ?','','text',true)+field('date','Pour quel jour ?',M.day||DATE(),'date',true),'Planifier')),
 task:d=>{const a=findAction(d.id);if(!a)return;if(a.kind==='routine'){const r=M.routines.find(r=>r.id===a.ref);if(!r)return;const s=routineSession(r,a.date);s.steps=s.labels.map(()=>a.done?'todo':'done');s.confirmed=!a.done;}else{const original=M.actions.find(x=>x.id===a.id);original.done=!a.done;}render();},
 'task-open':d=>{const a=findAction(d.id);if(a?.kind==='routine'&&M.routines.some(r=>r.id===a.ref))go('ROU-04',{context:{routine:a.ref,sessionDate:a.date}});else if(a?.session&&!M.routines.some(r=>r.id===a.ref))ACTIONS['session-detail']({id:a.session});else if(a?.ref)startTutorial(a.ref,{date:a.date});else ACTIONS['task-options'](d);},
 'task-options':d=>{const a=findAction(d.id);if(!a)return;M.context.action=d.id;modal('Ajuster cette action',form('reschedule',field('date','Nouvelle date',a.date,'date',true),'Reporter')+A('Retirer de cette journée','remove-action',{id:d.id},'text-button mt'));},
 'remove-action':d=>{const a=findAction(d.id);if(a?.kind==='routine')M.skippedOccurrences.push(a.ref+':'+a.date);M.actions=M.actions.filter(a=>a.id!==d.id);closeModal();render();},
 message:d=>{const m=M.messages.find(x=>x.id===d.id);if(!m)return;m.read=true;if(m.objectKey){const list=m.objectKey==='analysis'?M.analyses:M.events;if(!list.some(x=>x.id===m.objectId)){toast('Cet élément a été retiré.');return;}go(m.route,{context:{[m.objectKey]:m.objectId}});}else go(m.route);},
 open:d=>openItem(d.id),color:d=>go('COL-02',{context:{color:d.name}}),
 'domain-filter':d=>ACTIONS.catalog({domain:d.domain}),
 'domain-analysis':d=>{M.context.domain=d.domain;ACTIONS['new-analysis']();},
 'product-routine':()=>modal('Ajouter à une routine',M.routines.length?form('product-routine',select('routine','Choisir la routine',M.routines.map(r=>({value:r.id,label:r.name})),M.routines[0].id),'Ajouter le produit'):empty('Créez une routine','Vous pourrez ensuite y associer ce produit.','ROU-01','Mes routines'))
});
Object.assign(V,{
 'HAI-01':()=>head('Cheveux','Des idées pour votre texture, votre longueur, votre envie.')+chips(['Coiffures','Coupes','Couleurs'],'hairTab',M.hairTab||'Coiffures')+(M.hairTab==='Couleurs'?panel(`<h2>Une nuance à montrer au salon</h2>${P('Repérez les tons que vous aimez avant de parler de couleur avec votre coiffeur.')}${swatchGrid(PALETTE.filter(x=>['Caramel','Moka','Chocolat','Terre cuite'].includes(x[0])))}`):grid(M.hairTab==='Coupes'?['pixie','layers','sleek'].map(item):recommendations('Cheveux')))+B('Mes préférences cheveux','PRF-03','secondary mt')+A('Explorer toutes les idées','domain-filter',{domain:'Cheveux'},'text-button mt'),
 'COL-01':()=>{const p=PALETTES[M.context.palette]||PALETTES.palette;return head('Les couleurs que j’aime','Des associations à essayer, selon vos goûts.')+chips(['Chaudes','Fraîches','Neutres'],'paletteMood',p.mood)+swatchGrid(p.colors.slice(0,5))+swatchGrid(p.colors.slice(5))+P('Touchez une couleur pour explorer une association.')+A('Garder cette palette','save',{id:M.context.palette||'palette'})+B('Comment associer mes couleurs','DEC-05','secondary mt')+moreActions(A('Explorer mes envies de couleurs','domain-analysis',{domain:'Colorimétrie'},'secondary')+note('Palettes éditoriales. Aucune saison colorimétrique n’est déduite de votre visage.'))},
 'COL-02':()=>{const palette=PALETTES[M.context.palette]||PALETTES.palette,p=palette.colors.find(x=>x[0]===M.context.color)||palette.colors[0],base=palette.mood==='Fraîches'?[palette.colors[7],palette.colors[8]]:[PALETTE[6],PALETTE[8]];return head(esc(p[0]),'Une couleur, deux bases pour l’accompagner')+`<div class="color-sample" style="background:${p[1]}"></div>`+swatchGrid([p,...base])+P('Essayez cette couleur sur une pièce ou un accessoire. Gardez l’association dans laquelle vous vous sentez bien.')+A('Trouver une tenue','catalog',{domain:'Garde-robe',type:'Look'})+A('Garder cette palette','save',{id:M.context.palette||'palette'},'secondary mt')},
 'MAQ-01':()=>head('Maquillage','Choisissez votre envie, y compris celle de ne pas vous maquiller.')+chips(['Naturel','Soft glam','Soirée','Sans maquillage'],'makeupTab',M.makeupTab||'Naturel')+grid([item(({Naturel:'glam','Soft glam':'soft-glam',Soirée:'evening-look','Sans maquillage':'bare-face'})[M.makeupTab||'Naturel'])])+sec('Produits à explorer')+grid(CATALOG.filter(x=>x.type==='Produit')),
 'PEA-01':()=>head('Vos rituels','Les gestes que vous choisissez pour vous.')+row('Mes routines','Retrouver ou adapter mes gestes','ROU-01','sun')+row('Noter mon ressenti','Une observation, une photo si je le souhaite','PRO-03','leaf')+row('Mon journal','Retrouver mes observations','PRO-01','bookmark')+note('Les exemples ne constituent pas un diagnostic ni une prescription de soin.'),
 'GAR-01':()=>head('Une tenue pour vous','Pour votre quotidien et vos occasions.')+chips(['Quotidien','Travail','Rendez-vous','Événement'],'wardrobeTab',M.wardrobeTab||'Quotidien')+grid(CATALOG.filter(x=>x.domain==='Garde-robe'&&x.occasion===(M.wardrobeTab||'Quotidien')))+sec('Avec ce que vous avez')+row('Mon dressing','Mes vêtements, mes tenues composées','GAR-02','hanger')+A('Préparer une occasion','new-event',{},'secondary mt')
});
function swatchGrid(values){return `<div class="swatches">${values.map(([name,c])=>A(`<i style="--swatch:${c}"></i><span>${name}</span>`,'color',{name},'swatch')).join('')}</div>`;}
function lookContents(x){if(x.components)return sec('Votre composition')+Object.entries(x.components).map(([domain,id])=>A(`<span class="row-label"><span><strong>${esc(domain)}</strong><small>${esc(item(id)?.name||'Contenu indisponible')}</small></span></span>${icon('chev')}`,'open',{id},'glass list-row')).join('');if(x.pieces)return sec('Les pièces de cette tenue')+x.pieces.map(id=>{const c=M.clothes.find(x=>x.id===id);return c?A(`<span class="row-label"><strong>${esc(c.name)}</strong></span>${icon('chev')}`,'edit-clothing',{id},'glass list-row'):panel(P('Une pièce a été retirée du dressing.'));}).join('');return '';}
